DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.supply_edit_purchase(uuid,jsonb,jsonb,text)'::regprocedure) INTO definition; definition:=replace(definition,'FROM jsonb_object_keys(_changes) k WHERE k NOT IN','FROM jsonb_object_keys(_changes) AS keys(key_name) WHERE key_name NOT IN'); definition:=replace(definition,'FROM jsonb_object_keys(line) k WHERE k NOT IN','FROM jsonb_object_keys(line) AS keys(key_name) WHERE key_name NOT IN'); EXECUTE definition; END $$;